(() => {
  'use strict';
  const root=document.getElementById('bundle-root');if(!root)return;
  const $=id=>document.getElementById('bundle-'+id),base='/api/v1/deliverable-bundles',context=root.dataset.context;
  const goal=Number(root.dataset.goal)||null;let reviewed=null,selected=null,busy=false,pendingShare=null,responseAttempt=null;
  const id=()=>crypto.randomUUID().replaceAll('-','');
  function say(text){window.mvStatus($('status'),text);}
  function clearPrivate(){root.querySelectorAll('input,textarea').forEach(el=>{el.value='';});for(const name of ['inbox','items','preview-content','detail-files'])$(name).replaceChildren();$('source').hidden=true;$('detail').hidden=true;$('preview').hidden=true;reviewed=null;selected=null;pendingShare=null;}
  async function call(path,body){
    let value;
    try{value=await window.mvFetchJSON(base+path,{method:body?'POST':'GET',body,headers:{'X-Lightwork-Bundle-Context':context},timeout:30000,redirect:'error',onAccess:clearPrivate,messages:{401:'Access changed. Sign in and reload before continuing.',403:'Access changed. Sign in and reload before continuing.'}},body?'share the bundle':'load the bundles');}
    catch(error){if(error.status&&!error.accessChanged&&!error.timedOut)error.message='The operation could not be confirmed. Your saved bundle is unchanged. Refresh the page and try again.';if(error.status===404){$('detail').hidden=true;$('detail-files').replaceChildren();selected=null;}if(error.detail?.code==='context_changed')clearPrivate();throw error;}
    if(value.context!==context){clearPrivate();throw new Error('Your account or workspace changed. Reload this page.');}return value;
  }
  function node(tag,text){const el=document.createElement(tag);el.textContent=text;return el;}
  function choice(value,label){const el=node('option',label);el.value=value;return el;}
  function checkbox(name,value,label){const wrap=node('label',''),input=document.createElement('input');input.type='checkbox';input.name=name;input.value=value;wrap.append(input,document.createTextNode(' '+label));return wrap;}
  async function refresh(){const value=await call('');$('inbox').replaceChildren();for(const row of value.items){const item=node('p',''),button=node('button',row.name+' · '+row.status);button.type='button';button.className='btn';button.onclick=()=>load(row.id).catch(error=>say(error.message));item.append(button);$('inbox').append(item);}if(!value.items.length)$('inbox').append(node('p','No bundles have been shared with your account.'));say('Bundle inventory refreshed.');}
  async function source(){if(!goal)return;const value=await call('/sources/'+goal);$('source-description').textContent=value.source.title+' · '+value.source.status;if(!$('name').value)$('name').value=value.source.title+' — selected deliverables';$('recipient').replaceChildren(choice('','Choose a colleague'),...value.recipients.map(row=>choice(row.id,row.name)));$('items').replaceChildren(checkbox('include_result','true','Saved task result'));
    for(const row of value.source.artifacts)$('items').append(checkbox('artifact_ids',row.id,row.title+' · version '+row.version));
    for(const row of value.source.attachments)$('items').append(checkbox('attachment_ids',row.id,row.title+' · evidence file'));
    $('source').hidden=false;document.dispatchEvent(new CustomEvent('lightwork:copilot-selection',{detail:{selection:{kind:'goal',id:goal,goal_id:goal}}}));
  }
  function choices(){const form=$('form');return {name:$('name').value,recipient:$('recipient').value,note:$('note').value,unresolved:$('unresolved').value,lifetime:Number($('lifetime').value),include_result:!!form.querySelector('[name="include_result"]:checked'),artifact_ids:Array.from(form.querySelectorAll('[name="artifact_ids"]:checked'),e=>Number(e.value)),attachment_ids:Array.from(form.querySelectorAll('[name="attachment_ids"]:checked'),e=>Number(e.value))};}
  function lock(value){busy=value;for(const element of $('form').elements)element.disabled=value;$('share').disabled=value;}
  $('form').addEventListener('input',()=>{reviewed=null;$('preview').hidden=true;});
  $('form').addEventListener('submit',async event=>{event.preventDefault();if(busy||pendingShare)return;const input=choices();lock(true);try{const value=await call('/sources/'+goal+'/preview',input);reviewed={input,preview:value.preview};const panel=$('preview-content');panel.replaceChildren(node('p','Recipient: '+$('recipient').selectedOptions[0].textContent),node('p',input.note),node('p','Unresolved: '+(input.unresolved||'None declared; no completeness finding.')));for(const warning of value.preview.source_warnings||[])panel.append(node('p',warning));const list=node('ul','');for(const item of value.preview.items)list.append(node('li',item.title+(item.source.version?' · exact version '+item.source.version:'')+' · '+item.bytes+' bytes'));panel.append(list);$('preview').hidden=false;$('preview-title').focus();say('Review the exact selected items and recipient before confirming.');}catch(error){say(error.message);}finally{lock(false);}});
  $('share').addEventListener('click',async()=>{if(busy||!reviewed)return;if(!pendingShare)pendingShare={...reviewed.input,expected_review:reviewed.preview.review_version,operation_id:id()};lock(true);try{const value=await call('/sources/'+goal+'/share',pendingShare);pendingShare=null;reviewed=null;$('share').textContent='Confirm sharing these selected items';$('preview').hidden=true;await refresh();render(value.bundle);say('The selected bundle is shared with the named recipient. It has not been accepted or submitted externally.');lock(false);}catch(error){if(error.status>=400&&error.status<500){pendingShare=null;reviewed=null;$('preview').hidden=true;lock(false);say(error.message+' Your form is preserved; prepare a fresh preview.');return;}say(error.message+' Use Retry to check this same share request; it will not create a second bundle.');$('share').textContent='Retry this exact share request';$('share').disabled=false;busy=false;/* Preserve reviewed fields locked until the ambiguous request is resolved. */}});
  function render(row){document.dispatchEvent(new CustomEvent('lightwork:copilot-selection',{detail:{selection:{kind:'bundle',id:row.id}}}));selected=row;responseAttempt=null;const p=row.payload;$('detail-title').textContent=p.name;$('detail-state').textContent=(row.stale?'Source changed; acceptance is stale. ':row.acceptance_current?'Accepted by the named recipient. ':'No current human acceptance. ')+'Access '+row.status+'; expires '+(window.mvTimeAbsolute ? window.mvTimeAbsolute(row.expires_at) : new Date(row.expires_at*1000).toLocaleString())+'.';$('detail-note').textContent=p.note;$('detail-unresolved').textContent='Unresolved: '+(p.unresolved||'None declared by the author.');$('detail-files').replaceChildren();for(const item of p.items){const li=node('li',''),link=node('a',item.title+(item.source.version?' · version '+item.source.version:''));link.href=base+'/'+encodeURIComponent(row.id)+'/files/'+encodeURIComponent(item.key);link.download='';li.append(link);$('detail-files').append(li);}$('render').href=base+'/'+encodeURIComponent(row.id)+'/render';$('export').href=base+'/'+encodeURIComponent(row.id)+'/export';$('accept').hidden=!row.can_accept;$('revoke').hidden=!row.can_revoke;$('detail').hidden=false;const oldHandoff=document.getElementById('bundle-handoff-link');if(oldHandoff)oldHandoff.remove();if(row.can_revoke){const handoff=node('a','Offer a separate task handoff');handoff.id='bundle-handoff-link';handoff.href='/task-handoffs?bundle='+encodeURIComponent(row.id);$('detail').append(handoff);}$('detail-title').focus();}
  async function load(identifier){const value=await call('/'+encodeURIComponent(identifier));render(value.bundle);}
  async function respond(action){if(busy||!selected)return;const note=action==='accept'?$('accept-note').value:'';if(!responseAttempt)responseAttempt={action,note,expected_revision:selected.revision,operation_id:id()};if(responseAttempt.action!==action||responseAttempt.note!==note){say('Resolve the previous response using its unchanged comment before preparing a different decision.');return;}busy=true;$('accept-note').readOnly=true;$('revoke').disabled=true;try{const value=await call('/'+encodeURIComponent(selected.id)+'/respond',responseAttempt);render(value.bundle);say(action==='accept'?'Your human acceptance was recorded for this exact bundle.':'Future recipient access ended. Previously downloaded copies cannot be recalled.');await refresh();}catch(error){if(error.status>=400&&error.status<500){responseAttempt=null;say(error.message+' Your comment is preserved. Reopen the bundle before deciding again.');}else{say(error.message+' Retry the same response to check its receipt.');}}finally{busy=false;$('accept-note').readOnly=false;$('revoke').disabled=false;}}
  $('accept').addEventListener('submit',event=>{event.preventDefault();respond('accept');});$('revoke').onclick=()=>respond('revoke');$('refresh').onclick=()=>refresh().catch(error=>say(error.message));
  window.addEventListener('focus',()=>{if(!busy){refresh().catch(error=>say(error.message));if(selected&&!responseAttempt&&!pendingShare)load(selected.id).catch(error=>{$('detail').hidden=true;say(error.message);});}});
  Promise.all([refresh(),source()]).then(()=>{const requested=new URL(window.location.href).searchParams.get('open');if(requested)return load(requested);}).catch(error=>say(error.message));
})();
